import os,glob,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
def transform(g):
    h,w=len(g),len(g[0])
    rows={r for r in range(h) if len(set(g[r]))==1}
    cols={c for c in range(w) if len({g[r][c] for r in range(h)})==1}
    return [[2 if (r in rows or c in cols) else g[r][c] for c in range(w)] for r in range(h)]
for k in ['Demo pair 1','Demo pair 2']:
    print(k, transform(G[k+' input'])==G[k+' output'])
ti=G['Test input']; h,w=len(ti),len(ti[0])
fr=[r for r in range(h) if len(set(ti[r]))==1]
fc=[c for c in range(w) if len({ti[r][c] for r in range(h)})==1]
print("full rows",fr,"cols",fc)
out=transform(ti)
for row in out: print(' '.join(map(str,row)))
